package net.officefloor.hq.app.statement;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.SignedIn;
import net.officefloor.hq.app.claim.ClaimController.ClaimView;
import net.officefloor.hq.app.person.PersonController.PersonView;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.DeleteMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets/{sheetId}/people/{personId}/statements")
@Validated
public class StatementController {

    /** What the screen is told after a statement: the person and their claims, newest first. */
    public record StatementView(PersonView person, List<ClaimView> claims) {
    }

    private final StatementService service;

    public StatementController(StatementService service) {
        this.service = service;
    }

    /** The date a statement is taken as of; with none, the sheet's today. */
    public record StatementForm(LocalDate asOf) {
    }

    /** Take a statement for a person, as of a date on or before the sheet's today. */
    @PostMapping
    public StatementView take(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable long personId,
            @RequestHeader(SignedIn.HEADER) @NotBlank @Size(max = 200) String user,
            @RequestBody(required = false) StatementForm form) {
        StatementService.Stated stated = service.take(sheetId, SignedIn.name(user), personId,
                form == null ? null : form.asOf());
        return new StatementView(PersonView.of(stated.person()),
                stated.claims().stream().map(ClaimView::of).toList());
    }

    /** Cancel the person's last statement. */
    @DeleteMapping("/last")
    public StatementView cancel(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable long personId,
            @RequestHeader(SignedIn.HEADER) @NotBlank @Size(max = 200) String user) {
        StatementService.Stated stated = service.cancel(sheetId, SignedIn.name(user), personId);
        return new StatementView(PersonView.of(stated.person()),
                stated.claims().stream().map(ClaimView::of).toList());
    }
}
package net.officefloor.hq.app.statement;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/** A statement taken for a person: its number among theirs, its due-total (null when n/a) and date. */
@Entity
@Table(name = "person_statement")
public class Statement {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(name = "seq", nullable = false)
    private int seq;

    @Column(name = "total", precision = 14, scale = 2)
    private BigDecimal total;

    @Column(name = "taken_on", nullable = false)
    private LocalDate takenOn;

    protected Statement() {
    }

    public Statement(String sheetId, Long personId, int seq, BigDecimal total, LocalDate takenOn) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.seq = seq;
        this.total = total;
        this.takenOn = takenOn;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getPersonId() {
        return personId;
    }

    public int getSeq() {
        return seq;
    }

    public BigDecimal getTotal() {
        return total;
    }

    public LocalDate getTakenOn() {
        return takenOn;
    }

    /** Move the statement to a person (on a sheet) under a number among theirs. */
    public void moveTo(String sheetId, Long personId, int seq) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.seq = seq;
    }
}
package net.officefloor.hq.app.statement;

import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;

public interface StatementRepository extends JpaRepository<Statement, Long> {

    /** The person's statements, the last taken first. */
    List<Statement> findBySheetIdAndPersonIdOrderBySeqDesc(String sheetId, Long personId);
}
package net.officefloor.hq.app.statement;

import jakarta.persistence.EntityManager;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.Dues;
import net.officefloor.hq.app.history.SheetHistory;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleService;
import net.officefloor.hq.app.rollup.Rollups;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/**
 * A person's statements: taking one records their due-total on the sheet's today (or a date before it), binds each of
 * their counting claims to the due it shows then (late charge included), and leaves the rest unbound. A steward may
 * cancel the last one: the claims it bound are live again, and the person shows the one before it.
 */
@Service
public class StatementService {

    /** Shown in place of a due-total when the grade has no rate. */
    private static final String NO_RATE = "n/a";

    /** The person as stated, with all of their claims, newest first. */
    public record Stated(Person person, List<Claim> claims) {
    }

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final Dues dues;
    private final SheetHistory history;
    private final SheetService sheets;
    private final Rollups rollups;
    private final StatementRepository statements;
    private final RoleService roles;
    private final Audit audit;
    private final EntityManager entities;

    public StatementService(PersonRepository people, ClaimRepository claims, Dues dues, SheetHistory history,
            SheetService sheets, Rollups rollups, StatementRepository statements, RoleService roles, Audit audit,
            EntityManager entities) {
        this.entities = entities;
        this.rollups = rollups;
        this.statements = statements;
        this.roles = roles;
        this.people = people;
        this.claims = claims;
        this.dues = dues;
        this.history = history;
        this.sheets = sheets;
        this.audit = audit;
    }

    /**
     * Take a statement for a person on the sheet, as of a date on or before the sheet's today (null:
     * now). Their claims that counted at the end of that date are bound to the figures they had then,
     * every change made while the sheet's today was after it left out and that date standing in for
     * the sheet's today; every other claim of theirs is left unbound. Refused for a date after the
     * sheet's today, or one the sheet or the person was not yet kept on.
     */
    @Transactional
    public Stated take(String sheetId, String user, long personId, LocalDate asOf) {
        LocalDate today = sheets.today(sheetId);
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
        if (asOf != null && asOf.isAfter(today)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A statement cannot be taken as of a date after today.");
        }
        LocalDate day = asOf != null ? asOf : today;
        // On the sheet's today every change counts: the sheet as it stands now. Before it, as kept then.
        Person then;
        // Their claims as they stood then, by id.
        Map<Long, Claim> theirsThen = new LinkedHashMap<>();
        Dues.Basis basis;
        Sheet sheet;
        if (day.equals(today)) {
            then = person;
            claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId).forEach(c -> theirsThen.put(c.getId(), c));
            basis = dues.live(sheetId);
            sheet = sheets.load(sheetId);
        } else {
            SheetHistory.AsOf kept = history.at(sheetId, day).orElseThrow(() -> notYet(day));
            then = kept.people().get(personId);
            if (then == null) {
                throw notYet(day);
            }
            kept.claims().forEach((id, c) -> {
                if (c.getPersonId() == personId) {
                    theirsThen.put(id, c);
                }
            });
            basis = kept.basis();
            sheet = kept.sheet();
        }
        Rollups.Rollup before = rollups.take(sheetId);
        Map<Long, BigDecimal> bound = new HashMap<>();
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        boolean figured = false;
        int counted = 0;
        for (Map.Entry<Long, Claim> entry : theirsThen.entrySet()) {
            Claim claim = entry.getValue();
            // As in the live totals: an OPEN or PENDING claim held or dated within a hold, or of a person whose
            // retirement date is reached, and not bound, is left
            // out, as is a claim deferred on the day.
            if (!then.countsLive(claim.getStatus(), claim.getDate(), claim.isStated(), claim.isDeferredOn(day), day, claim.isHeld())) {
                continue;
            }
            // The statement binds the due as shown, late charge and floor included: a figure an earlier
            // statement bound stays as it is.
            BigDecimal due = dues.due(claim, then.gradeOn(claim.getDate()), basis);
            figured |= due != null;
            bound.put(entry.getKey(), due);
            counted++;
            if (due != null) {
                total = total.add(due);
            }
        }
        // As on the screen: n/a when the grade in force on the day has no rate, unless a claim has a figure.
        if (basis.rateInForce(then.gradeOn(day), day).isEmpty() && !figured) {
            total = null;
        }
        // A due-total is at most the cap in force on the day. The claims they have now are bound by id.
        total = sheet.capped(total);
        List<Claim> theirs = claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId);
        for (Claim claim : theirs) {
            if (bound.containsKey(claim.getId())) {
                claim.bind(bound.get(claim.getId()));
            } else {
                claim.unbind();
            }
        }
        person.stated(total, day);
        Person saved = people.saveAndFlush(person);
        statements.saveAndFlush(new Statement(sheetId, saved.getId(), saved.getStatementCount(), total, day));
        // The person shows the statement just taken among their lines.
        entities.refresh(saved);
        List<Claim> stated = claims.saveAllAndFlush(theirs);
        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + saved.getName()
                + " due-total=" + (total != null ? total.toPlainString() : NO_RATE) + " claims=" + counted
                + (asOf != null ? " asof=" + asOf : ""));
        rollups.audit(sheetId, user, before);
        return new Stated(saved, stated);
    }

    /**
     * Hand a person's statements to another they join (on the other's sheet): the other's count
     * becomes their own plus theirs, numbered with theirs first, and the other's last statement stays
     * the other's, or, having none, becomes theirs. The caller saves the other.
     */
    public void handOver(String fromSheetId, Person from, Person into) {
        int moved = from.getStatementCount();
        List<Statement> intos = statements.findBySheetIdAndPersonIdOrderBySeqDesc(into.getSheetId(), into.getId());
        // The other's own are numbered after theirs, the last first so no two share a number.
        for (Statement statement : intos) {
            statement.moveTo(into.getSheetId(), into.getId(), statement.getSeq() + moved);
            statements.saveAndFlush(statement);
        }
        for (Statement statement : statements.findBySheetIdAndPersonIdOrderBySeqDesc(fromSheetId, from.getId())) {
            statement.moveTo(into.getSheetId(), into.getId(), statement.getSeq());
            statements.saveAndFlush(statement);
        }
